PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','technician','manager')),password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repair_requests(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES users(id),preferred_technician_id TEXT REFERENCES users(id),device TEXT NOT NULL,type TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,customer_note TEXT NOT NULL,submitted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS repair_jobs(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE REFERENCES repair_requests(id),assigned_technician_id TEXT REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('To Do','In Progress','Waiting','Awaiting Customer Confirmation','Completed')),progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),version INTEGER NOT NULL DEFAULT 1,current_approval_request_id TEXT REFERENCES approval_requests(id),received_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignment_history(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),from_technician_id TEXT REFERENCES users(id),to_technician_id TEXT NOT NULL REFERENCES users(id),actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS handovers(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),author_id TEXT NOT NULL REFERENCES users(id),tests TEXT NOT NULL,finding TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS help_requests(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),requester_id TEXT NOT NULL REFERENCES users(id),helper_id TEXT NOT NULL REFERENCES users(id),problem TEXT NOT NULL,blocking INTEGER NOT NULL CHECK(blocking IN (0,1)),status TEXT NOT NULL CHECK(status IN ('Open','Accepted','Resolved')),appreciated INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,accepted_at TEXT,resolved_at TEXT,CHECK(requester_id<>helper_id));
CREATE TABLE IF NOT EXISTS help_comments(id TEXT PRIMARY KEY,help_request_id TEXT NOT NULL REFERENCES help_requests(id),author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),requested_by_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,description TEXT NOT NULL,additional_cost INTEGER NOT NULL CHECK(additional_cost>=0),revised_total INTEGER CHECK(revised_total>=0),currency TEXT NOT NULL DEFAULT 'AUD',alternative TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','declined','clarification','withdrawn','superseded')),withdrawal_reason TEXT,created_at TEXT NOT NULL,closed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_approval ON approval_requests(job_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS approval_responses(id TEXT PRIMARY KEY,approval_request_id TEXT NOT NULL UNIQUE REFERENCES approval_requests(id),customer_id TEXT NOT NULL REFERENCES users(id),decision TEXT NOT NULL CHECK(decision IN ('approved','declined','clarification')),note TEXT NOT NULL,responded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parts_requests(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),reported_by_id TEXT NOT NULL REFERENCES users(id),owner_id TEXT REFERENCES users(id),part_description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),blocking INTEGER NOT NULL CHECK(blocking IN (0,1)),status TEXT NOT NULL CHECK(status IN ('Reported','Awaiting approval','Ordered','Received')),next_action TEXT NOT NULL,expected_arrival TEXT,procurement TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parts_followups(id TEXT PRIMARY KEY,parts_request_id TEXT NOT NULL REFERENCES parts_requests(id),actor_id TEXT NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public_updates(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),published_by_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,next_action TEXT NOT NULL,action_required INTEGER NOT NULL CHECK(action_required IN (0,1)),status_at_publication TEXT NOT NULL,published_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_messages(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS completion_confirmations(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES repair_jobs(id),customer_id TEXT NOT NULL REFERENCES users(id),confirmed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS repair_logs(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES repair_jobs(id),uploaded_by_id TEXT NOT NULL REFERENCES users(id),visibility TEXT NOT NULL CHECK(visibility IN ('public','internal')),filename TEXT NOT NULL,mime TEXT NOT NULL,content BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_assignee ON repair_jobs(assigned_technician_id);
CREATE INDEX IF NOT EXISTS requests_customer ON repair_requests(customer_id);
CREATE INDEX IF NOT EXISTS help_recipient ON help_requests(helper_id,status);
PRAGMA user_version=1;
